import itertools
TC={'1':np.ones_like(T),'T':T,'T2':T**2,'T3':T**3,'1/T':1/T,'lnT':np.log(T),'sqT':np.sqrt(T),'expmT':np.exp(-T),'expT':np.exp(T),'1/T2':1/T**2}
EB=[np.ones_like(eps),np.log(eps),1/eps,eps**2]
names=list(TC)
sets=[]
for k in [2,3,4]:
    sets+= [s for s in itertools.combinations(names,k)]
choice=[('1','T','T2','T3')]*4
def build(ch):
    return np.column_stack([EB[i]*TC[b] for i in range(4) for b in ch[i]])
def err(ch):
    X=build(ch); c=np.linalg.lstsq(X,sigma,rcond=None)[0]
    return np.mean((sigma-X@c)**2)/np.var(sigma)
ch=list(choice); cur=err(ch)
for rnd in range(3):
    for i in range(4):
        for s in sets:
            t=list(ch); t[i]=s
            e=err(t)
            if e<cur: cur=e; ch=t
    print('round',rnd,cur,ch)
